// Typed wrappers around the account methods Wails exposes on main.App.
//
// They live outside web/wailsjs on purpose: that folder is generated by
// `wails generate module`, and the account surface is small enough to keep
// one hand-written, typed client instead of regenerating (and re-reviewing)
// the whole binding tree. Method names must match app_accounts.go exactly.
import type {
  AccountInput,
  AccountsState,
  AccountView,
  Rotation,
  SwitchResult,
} from './types';

type GoApp = Record<string, (...args: unknown[]) => Promise<unknown>>;

function goApp(): GoApp {
  const bridge = window as unknown as { go?: { main?: { App?: GoApp } } };
  const app = bridge.go?.main?.App;
  if (!app) {
    throw new Error('Wails bridge unavailable — run the desktop app to manage accounts');
  }
  return app;
}

function call<T>(method: string, ...args: unknown[]): Promise<T> {
  const app = goApp();
  const fn = app[method];
  if (typeof fn !== 'function') {
    return Promise.reject(new Error(`Method ${method} is not exposed by this build`));
  }
  return fn(...args) as Promise<T>;
}

export const getAccounts = () => call<AccountsState>('GetAccounts');

export const createAccount = (input: AccountInput) =>
  call<AccountView>('CreateAccount', input);

export const updateAccount = (id: string, input: AccountInput) =>
  call<AccountView>('UpdateAccount', id, input);

export const deleteAccount = (id: string) => call<void>('DeleteAccount', id);

export const resetAccountUsage = (id: string) =>
  call<void>('ResetAccountUsage', id);

export const setRotation = (rotation: Rotation) =>
  call<void>('SetRotation', rotation);

export const switchAccount = (id: string, start: boolean) =>
  call<SwitchResult>('SwitchAccount', id, start);
